// === Tab: mySketch ===
function setup() {
  // createCanvas(windowWidth, windowHeight);
  createCanvas(1000, 1000);
  MAX = width > height ? width : height;
  angleMode(DEGREES);
  colorMode(HSB, 360)
  // noStroke();
  stroke(360)
  loadNodes();
}
let SPACE = 50
let n = [];
let MAX;
let NOISE_VAL = 0.008;
let NOISE_VAL2 = 0.002;

function draw() {
  background(0);
  displayNodes()
}

displayNodes = () => {

  for (let i = 0; i < MAX / SPACE; i++) {
    for (let j = 0; j < MAX / (SPACE / 2) * sqrt(3); j++) {
      n[i][j].move();
      stroke((frameCount + n[i][j].a) % 360, 360, 360);

      if (i < MAX / SPACE - 1) {
        line(n[i][j].nx, n[i][j].ny, n[i + 1][j].nx, n[i + 1][j].ny)
      }
      if (j < MAX / (SPACE / 2) * sqrt(3) - 1) {
        line(n[i][j].nx, n[i][j].ny, n[i][j + 1].nx, n[i][j + 1].ny)
        if (i > 0 && i < MAX / SPACE - 1) {
          if (j % 2 === 0) {
            line(n[i][j].nx, n[i][j].ny, n[i + 1][j + 1].nx, n[i + 1][j + 1].ny)
          } else {
            line(n[i][j].nx, n[i][j].ny, n[i - 1][j + 1].nx, n[i - 1][j + 1].ny)

          }
        }
      }

    }
  }
  for (let i = 0; i < MAX / SPACE; i++) {
    for (let j = 0; j < MAX / (SPACE / 2) * sqrt(3); j++) {

      n[i][j].display();
    }
  }
}

loadNodes = () => {
  for (let i = 0; i < MAX / SPACE; i++) {
    row = []
    for (let j = 0; j < MAX / (SPACE / 2) * sqrt(3); j++) {

      let offset = 0;
      if (j % 2 === 0) {
        offset = SPACE / 2;
      }
      row.push(new Node(i * SPACE + offset, j * (SPACE / 2) * sqrt(3), i, j));

    }
    n.push(row)
  }
}

class Node {
  constructor(x, y, i, j) {
    this.x = x;
    this.y = y;
    this.nx = this.x + sin(this.a) * SPACE / 4;
    this.ny = this.y + cos(this.a) * SPACE / 4;
    this.a = 0
    this.i = i;
    this.j = j
  }

  display() {
    this.nx = this.x + sin(this.a) * SPACE / 4;
    this.ny = this.y + cos(this.a) * SPACE / 4;
    let s = noise(NOISE_VAL * this.y, NOISE_VAL * this.x, NOISE_VAL * frameCount)

    fill((frameCount + this.a) % 360, 360, 360);
    stroke(360)
    ellipse(this.nx, this.ny, SPACE / 2 * s, SPACE / 2 * s);


  }
  move() {

    this.a += noise(NOISE_VAL2 * this.x, NOISE_VAL2 * this.y, NOISE_VAL2 * frameCount) * 4;
  }

}
